import {selectCalendarDate} from './calendar-picker-actions.mjs';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';import{readFile,writeFile}from'node:fs/promises';import{load}from'cheerio';import{chromium}from'playwright';import{serveStatic}from'../../engine/static.mjs';import{collectCalendarPresentation,calendarPresentation}from'../../scripts/calendar-presentation.mjs';import{applyComponents}from'../../scripts/component-export.mjs';import{parseContent}from'../../scripts/source-project.mjs';import path from'node:path';
const generated=process.argv.includes('--generated');
const artifact=path.resolve('artifacts/platform/events-heldout'),project=path.join(artifact,'project'),routes=JSON.parse(await readFile(path.join(project,'routes.json'))),events=[];
for(const r of routes.filter(r=>r.route.startsWith('/event/'))){const p=parseContent(await readFile(path.join(project,'content',r.collection,r.slug+'.md'),'utf8'),'event');events.push({route:r.route,title:p.meta.title,start:p.meta.event.start,end:p.meta.event.end,allDay:p.meta.event.all_day,description:p.meta.description,venue:p.meta.event.venue.venue});}
const manifest={schema:'website-cloner-calendar/v1',events},registry=new Map();for(const r of routes.filter(r=>r.route.startsWith('/events/'))){const $=load(await readFile(path.join(project,'output',r.route,'index.html'),'utf8'));collectCalendarPresentation($,{manifestRoute:'/assets/test-calendar.json',manifest},registry);}const presentation=calendarPresentation([...registry.values()][0]);assert.deepEqual(presentation.missing,[]);
let server,browser;const cases=[];try{server=await serveStatic(path.join(project,'output'));browser=await chromium.launch({channel:'chrome'});for(const width of [1440,390]){const page=await browser.newPage({viewport:{width,height:900}});const route='/events/2028-03-11/';if(!generated)await page.route(server.url+'/**',async r=>{const url=new URL(r.request().url());if(url.pathname==='/assets/test-calendar.json')return r.fulfill({json:manifest});if(url.pathname==='/assets/test-calendar.presentation.json')return r.fulfill({json:presentation});if(url.pathname===route||url.pathname==='/events/'){const $=load(await readFile(path.join(project,'output',url.pathname,'index.html'),'utf8'));$('.tribe-events-view').attr('data-migration-calendar','/assets/test-calendar.json');applyComponents($);return r.fulfill({contentType:'text/html',body:$.html()});}return r.continue();});await page.goto(server.url+route,{waitUntil:'networkidle'});
const next=page.locator('.tribe-events-c-top-bar__nav-link--next:visible,.tribe-events-c-nav__next:visible').first();await next.click();await page.waitForURL('**calendar-date=2028-03-12');assert.match(await next.getAttribute('href'),/calendar-date=2028-03-13/);assert.equal(await page.locator('.tribe-events-calendar-day__event').count(),1);await next.click();await page.waitForURL('**calendar-date=2028-03-13');await next.click();await page.waitForURL('**calendar-date=2028-03-14');assert.equal(await page.locator('.tribe-events-calendar-day__event').count(),0);
await selectCalendarDate(page,'2028-06-17');await page.waitForURL('**calendar-date=2028-06-17');assert.match(await page.locator('.tribe-events-calendar-day').textContent(),/Open Studio Day/);assert.match(await page.locator('.tribe-events-calendar-day__type-separator').textContent(),/All Day/);await page.goBack();await page.waitForFunction(()=>document.querySelector('.tribe-events-calendar-day__event')===null);for(let i=0;i<3;i++)await page.goBack();await page.waitForURL(server.url+route);await page.waitForFunction(()=>document.querySelector('.tribe-events-calendar-day__event')!==null);await page.goto(server.url+'/events/',{waitUntil:'networkidle'});await selectCalendarDate(page,'2028-07-01');await page.waitForURL('**calendar-date=2028-07-01');assert.equal(await page.locator('.tribe-events-calendar-list__event-row').count(),2);assert.match(await page.locator('.tribe-events-calendar-list').textContent(),/Summer Residency/);assert.doesNotMatch(await page.locator('.tribe-events-calendar-list').textContent(),/Coastal Design Lab/);cases.push({runtimeSHA256:createHash('sha256').update(await page.locator('script[data-cloner-component=calendar]').textContent()).digest('hex'),width,dayNavigation:true,emptyDay:true,allDayPicker:true,history:true,listDateFilter:true});await page.close();}await writeFile(path.join(artifact,generated?'local-calendar-generated-check.json':'local-calendar-candidate-check.json'),JSON.stringify({scope:generated?'Actual generated export day controls; month/picker parity remains pending':'Candidate runtime with installed export fragments; not a rebuilt-export or full calendar acceptance',cases},null,2));console.log(JSON.stringify({cases:cases.length}));}finally{await browser?.close();await server?.close();}
